--
-- Name: fn_check_borrow(integer, integer, date, date, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_check_borrow(p_borrower_id integer, p_equipment_id integer, p_borrow_date date, p_due_date date, p_status character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_borrower_id IS NULL OR p_equipment_id IS NULL THEN
        RAISE EXCEPTION 'Borrower and equipment are required.';
    END IF;
    IF p_borrow_date IS NULL OR p_due_date IS NULL THEN
        RAISE EXCEPTION 'Borrow date and due date are required.';
    END IF;
    IF p_due_date < p_borrow_date THEN
        RAISE EXCEPTION 'Due date cannot be earlier than the borrow date.';
    END IF;
    IF p_status IS NULL OR p_status NOT IN ('Active', 'Returned', 'Overdue') THEN
        RAISE EXCEPTION 'Status must be Active, Returned or Overdue.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM borrowers WHERE borrower_id = p_borrower_id) THEN
        RAISE EXCEPTION 'Borrower #% does not exist.', p_borrower_id;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM equipment WHERE equipment_id = p_equipment_id) THEN
        RAISE EXCEPTION 'Equipment #% does not exist.', p_equipment_id;
    END IF;
END;
$$;


--
-- Name: sp_delete_borrow(integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_delete_borrow(IN p_id integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM borrow_transactions WHERE borrow_id = p_id) THEN
        RAISE EXCEPTION 'Transaction #% does not exist.', p_id;
    END IF;

    DELETE FROM borrow_items        WHERE borrow_id = p_id;
    DELETE FROM borrow_transactions WHERE borrow_id = p_id;
END;
$$;


--
-- Name: sp_delete_borrower(integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_delete_borrower(IN p_id integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM borrowers WHERE borrower_id = p_id) THEN
        RAISE EXCEPTION 'Borrower #% does not exist.', p_id;
    END IF;
    IF EXISTS (SELECT 1 FROM borrow_transactions WHERE borrower_id = p_id) THEN
        RAISE EXCEPTION 'This borrower has transactions and cannot be deleted.';
    END IF;

    DELETE FROM borrowers WHERE borrower_id = p_id;
END;
$$;


--
-- Name: sp_delete_equipment(integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_delete_equipment(IN p_id integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM equipment WHERE equipment_id = p_id) THEN
        RAISE EXCEPTION 'Equipment #% does not exist.', p_id;
    END IF;
    IF EXISTS (SELECT 1 FROM borrow_items WHERE equipment_id = p_id) THEN
        RAISE EXCEPTION 'This equipment is used in transactions and cannot be deleted.';
    END IF;

    DELETE FROM equipment WHERE equipment_id = p_id;
END;
$$;


--
-- Name: sp_insert_borrow(integer, integer, date, date, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_insert_borrow(IN p_borrower_id integer, IN p_equipment_id integer, IN p_borrow_date date, IN p_due_date date, IN p_status character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id integer;
BEGIN
    PERFORM fn_check_borrow(p_borrower_id, p_equipment_id, p_borrow_date, p_due_date, p_status);

    VALUES (p_borrower_id, p_borrow_date, p_due_date, p_status)
    RETURNING borrow_id INTO v_id;

    VALUES (v_id, p_equipment_id, 1);
END;
$$;


--
-- Name: sp_insert_borrower(character varying, character varying, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_insert_borrower(IN p_borrower_no character varying, IN p_full_name character varying, IN p_borrower_type character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    p_borrower_no   := btrim(COALESCE(p_borrower_no, ''));
    p_full_name     := btrim(COALESCE(p_full_name, ''));
    p_borrower_type := btrim(COALESCE(p_borrower_type, ''));

    IF p_borrower_no = '' OR p_full_name = '' OR p_borrower_type = '' THEN
        RAISE EXCEPTION 'Borrower no., full name and type are all required.';
    END IF;
    IF length(p_borrower_no) > 20 THEN
        RAISE EXCEPTION 'Borrower no. must be 20 characters or fewer.';
    END IF;
    IF length(p_full_name) > 100 THEN
        RAISE EXCEPTION 'Full name must be 100 characters or fewer.';
    END IF;
    IF length(p_borrower_type) > 50 THEN
        RAISE EXCEPTION 'Type must be 50 characters or fewer.';
    END IF;
    IF EXISTS (SELECT 1 FROM borrowers WHERE borrower_no = p_borrower_no) THEN
        RAISE EXCEPTION 'Borrower no. % is already in use.', p_borrower_no;
    END IF;

    VALUES (p_borrower_no, p_full_name, p_borrower_type);
END;
$$;


