CREATE PROCEDURE public.sp_insert_equipment(IN p_property_no character varying, IN p_equipment_name character varying, IN p_quantity_available integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    p_property_no    := btrim(COALESCE(p_property_no, ''));
    p_equipment_name := btrim(COALESCE(p_equipment_name, ''));

    IF p_property_no = '' OR p_equipment_name = '' THEN
        RAISE EXCEPTION 'Property no. and equipment name are required.';
    END IF;
    IF p_quantity_available IS NULL OR p_quantity_available < 0 THEN
