        RAISE EXCEPTION 'Property no. (max 20) or equipment name (max 100) is too long.';
    END IF;
    IF EXISTS (SELECT 1 FROM equipment WHERE property_no = p_property_no) THEN
        RAISE EXCEPTION 'Property no. % is already in use.', p_property_no;
    END IF;

    VALUES (p_property_no, p_equipment_name, p_quantity_available);
END;
$$;


--
-- Name: sp_update_borrow(integer, integer, integer, date, date, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_update_borrow(IN p_id integer, IN p_borrower_id integer, IN p_equipment_id integer, IN p_borrow_date date, IN p_due_date date, IN p_status character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM borrow_transactions WHERE borrow_id = p_id) THEN
        RAISE EXCEPTION 'Transaction #% does not exist.', p_id;
    END IF;
    PERFORM fn_check_borrow(p_borrower_id, p_equipment_id, p_borrow_date, p_due_date, p_status);

    UPDATE borrow_transactions
       SET borrower_id = p_borrower_id,
           borrow_date = p_borrow_date,
           due_date    = p_due_date,
           status      = p_status
     WHERE borrow_id = p_id;

    UPDATE borrow_items SET equipment_id = p_equipment_id WHERE borrow_id = p_id;
    IF NOT FOUND THEN
        VALUES (p_id, p_equipment_id, 1);
    END IF;
END;
$$;


