CREATE PROCEDURE public.sp_update_borrower(IN p_id integer, IN p_borrower_no character varying, IN p_full_name character varying, IN p_borrower_type character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    p_borrower_no   := btrim(COALESCE(p_borrower_no, ''));
    p_full_name     := btrim(COALESCE(p_full_name, ''));
    p_borrower_type := btrim(COALESCE(p_borrower_type, ''));

    IF NOT EXISTS (SELECT 1 FROM borrowers WHERE borrower_id = p_id) THEN
        RAISE EXCEPTION 'Borrower #% does not exist.', p_id;
    END IF;
    IF p_borrower_no = '' OR p_full_name = '' OR p_borrower_type = '' THEN
        RAISE EXCEPTION 'Borrower no., full name and type are all required.';
    END IF;
    IF length(p_borrower_no) > 20 OR length(p_full_name) > 100 OR length(p_borrower_type) > 50 THEN
        RAISE EXCEPTION 'One of the values is too long (max 20 / 100 / 50 characters).';
    END IF;
    IF EXISTS (SELECT 1 FROM borrowers
               WHERE borrower_no = p_borrower_no AND borrower_id <> p_id) THEN
        RAISE EXCEPTION 'Borrower no. % is already in use.', p_borrower_no;
    END IF;

    UPDATE borrowers
       SET borrower_no   = p_borrower_no,
           full_name     = p_full_name,
           borrower_type = p_borrower_type
     WHERE borrower_id = p_id;
END;
$$;


