--
-- Name: v_student_account_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_student_account_report AS
 SELECT s.student_no,
    (((s.first_name)::text || ' '::text) || (s.last_name)::text) AS student_name,
    s.program,
    COALESCE(a.net_assessment, (0)::numeric) AS net_assessment,
    COALESCE(p.total_payments, (0)::numeric) AS total_payments,
    (COALESCE(a.net_assessment, (0)::numeric) - COALESCE(p.total_payments, (0)::numeric)) AS remaining_balance,
        CASE
            WHEN (COALESCE(a.net_assessment, (0)::numeric) = (0)::numeric) THEN 'No Assessment'::text
            WHEN (COALESCE(p.total_payments, (0)::numeric) = (0)::numeric) THEN 'Unpaid'::text
            WHEN (COALESCE(p.total_payments, (0)::numeric) > a.net_assessment) THEN 'Overpaid'::text
            WHEN (COALESCE(p.total_payments, (0)::numeric) = a.net_assessment) THEN 'Fully Paid'::text
            ELSE 'Partially Paid'::text
        END AS account_classification
   FROM ((public.students s
     LEFT JOIN ( SELECT assessments.student_id,
            sum((assessments.gross_amount - assessments.discount_amount)) AS net_assessment
           FROM public.assessments
          GROUP BY assessments.student_id) a ON ((a.student_id = s.student_id)))
     LEFT JOIN ( SELECT payment_entries.student_id,
            sum(payment_entries.amount) AS total_payments
           FROM public.payment_entries
          GROUP BY payment_entries.student_id) p ON ((p.student_id = s.student_id)));


